script:
if doc.voucher_type == "Loan Repayment" and doc.account == "Payroll Payable - ROC":
    applicant = frappe.db.get_value("Loan Repayment", doc.voucher_no, "applicant")
    if applicant:
        doc.party_type = "Employee"
        doc.party = applicant

# Check if someone checked or unchecked the "Disabled" box
if doc.has_value_changed("disabled"):

    # SCENARIO 1: Officer leaves (Disabled is checked / True)
    if doc.disabled == 1:
        # Find all Active subscriptions for this officer
        active_subs = frappe.get_all("Subscription", 
            filters={"party": doc.name, "status": "Active"}
        )
        for sub in active_subs:
            # Change status to Paused safely
            frappe.db.set_value("Subscription", sub.name, "status", "Paused")
            frappe.msgprint(f"Subscription {sub.name} automatically Paused because member was disabled.")

    # SCENARIO 2: Officer returns (Disabled is unchecked / False)
    elif doc.disabled == 0:
        # Find all Paused subscriptions for this officer
        paused_subs = frappe.get_all("Subscription", 
            filters={"party": doc.name, "status": "Paused"}
        )
        for sub in paused_subs:
            # Change status back to Active
            frappe.db.set_value("Subscription", sub.name, "status", "Active")
            frappe.msgprint(f"Subscription {sub.name} automatically Resumed. Welcome back!")

# ENFORCE RULE: Only 1 Active Subscription per Member allowed
if doc.status == "Active" and doc.party_type == "Customer":
    existing_sub = frappe.db.exists(
        "Subscription", 
        {
            "party": doc.party, 
            "status": "Active", 
            "name": ["!=", doc.name] # Ignore the one currently being saved
        }
    )
    if existing_sub:
        frappe.throw(f"Stop! This member already has an Active subscription ({existing_sub}). You must cancel or pause the old one before creating a new one.")

# SAFETY CHECK: Do not attempt to create prices or UOMs for Template Items
if not doc.has_variants:

    prices_to_sync = []
    base_uom = doc.stock_uom or "Nos"
    standard_rate = float(doc.standard_rate or 0)

    # ------------------------------------------------------------------
    # PART A: DYNAMIC TREE CHECK (Catching all Sub-Groups)
    # ------------------------------------------------------------------
    target_parents = ["Food & Beverages", "Liquor"]
    is_pos_item = False
    is_liquor = False # Specifically tracking Liquor for UOM automation

    # Get bounds for Parent groups
    parent_bounds = frappe.db.get_all("Item Group", 
        filters={"name": ["in", target_parents]}, 
        fields=["name", "lft", "rgt"]
    )

    # Get bounds for the current Item's group
    current_group = frappe.db.get_value("Item Group", doc.item_group, ["lft", "rgt"], as_dict=1)

    if current_group and parent_bounds:
        for p in parent_bounds:
            if current_group.lft >= p.lft and current_group.rgt <= p.rgt:
                is_pos_item = True
                if p.name == "Liquor":
                    is_liquor = True
                break

    # ------------------------------------------------------------------
    # PART B: AUTOMATIC UOM GENERATION (Executes FIRST)
    # ------------------------------------------------------------------
    smalls_rate = float(doc.custom_smalls_rate or 0)

    if is_liquor and smalls_rate > 0.0:
        has_small_uom = False
        for row in doc.get("uoms", []):
            if row.uom == "Small (30ml)":
                has_small_uom = True
                break

        # Automatically calculate fraction and append row if missing
        if not has_small_uom:
            conv_factor = 0.0
            if "750" in base_uom:
                conv_factor = 1.0 / 24.0
            elif "1000" in base_uom:
                conv_factor = 1.0 / 32.0
            elif "375" in base_uom:
                conv_factor = 1.0 / 12.0

            if conv_factor > 0:
                doc.append("uoms", {
                    "uom": "Small (30ml)",
                    "conversion_factor": conv_factor
                })

    # ------------------------------------------------------------------
    # PART C: F&B AND LIQUOR PRICING (Explicit UOM Mapping)
    # ------------------------------------------------------------------
    if is_pos_item:
        bottle_rate = float(doc.standard_rate or 0)

        # Map rates directly to the explicit UOM names from the child table
        if doc.get("uoms"):
            for row in doc.get("uoms"):
                if "Bottle" in row.uom and bottle_rate > 0.0:
                    prices_to_sync.append({"price_list": "Standard Selling", "rate": bottle_rate, "uom": row.uom})
                elif row.uom == "Small (30ml)" and smalls_rate > 0.0:
                    prices_to_sync.append({"price_list": "Standard Selling", "rate": smalls_rate, "uom": row.uom})

        if not doc.get("uoms") and bottle_rate > 0.0:
            prices_to_sync.append({"price_list": "Standard Selling", "rate": bottle_rate, "uom": base_uom})

    # ------------------------------------------------------------------
    # PART D: TIERED MEMBERSHIP PRICING (Sports, Rooms, Guest Fees)
    # ------------------------------------------------------------------
    else:
        # 1. Sync the Standard Selling Price List (Guest Rate)
        if standard_rate > 0.0:
            prices_to_sync.append({"price_list": "Standard Selling", "rate": standard_rate, "uom": base_uom})

        # 2. Member Fallback Logic 
        railway_rate = float(doc.custom_railway_member_rate or 0)
        non_railway_rate = float(doc.custom_nonrailway_member_rate or 0)

        if railway_rate == 0.0:
            railway_rate = standard_rate
        if non_railway_rate == 0.0:
            non_railway_rate = standard_rate

        # Sync Member Price Lists
        if railway_rate > 0.0:
            prices_to_sync.append({"price_list": "Railway Member Rate", "rate": railway_rate, "uom": base_uom})
        if non_railway_rate > 0.0:
            prices_to_sync.append({"price_list": "Non-Railway Member Rate", "rate": non_railway_rate, "uom": base_uom})

    # ------------------------------------------------------------------
    # PART E: EXECUTE DATABASE UPDATES (Item Price Sync)
    # ------------------------------------------------------------------
    for p in prices_to_sync:
        existing_price = frappe.db.get_value("Item Price", {
            "item_code": doc.name, 
            "price_list": p["price_list"],
            "uom": p["uom"]
        }, "name")

        if existing_price:
            frappe.db.set_value("Item Price", existing_price, "price_list_rate", p["rate"])
        else:
            new_price = frappe.get_doc({
                "doctype": "Item Price",
                "item_code": doc.name,
                "price_list": p["price_list"],
                "price_list_rate": p["rate"],
                "uom": p["uom"]
            })
            new_price.insert(ignore_permissions=True)

if doc.is_pos:
    credit_deduction = 0.0
    
    # Loop through the payment table to find if 'Customer Account' was used
    for row in doc.get('payments', []):
        if row.mode_of_payment == "Customer Account" and row.amount > 0:
            # Capture the amount, then force the row to zero
            credit_deduction += float(row.amount or 0.0)
            row.amount = 0.0
            row.base_amount = 0.0
            
    # If a credit amount was found, deduct it from the total paid amount
    if credit_deduction > 0:
        doc.paid_amount = float(doc.paid_amount or 0.0) - credit_deduction
        doc.base_paid_amount = float(doc.base_paid_amount or 0.0) - credit_deduction

# Define the Item Group that must be protected
RESTRICTED_GROUP = "Hall & Venue Rental"

for item in doc.items:
    # Check if the item belongs to the Venue group
    item_group = frappe.db.get_value("Item", item.item_code, "item_group")
    
    if item_group == RESTRICTED_GROUP:
        # Check if this row is linked to a Sales Order
        # Manual/Direct invoices have 'sales_order' as None
        if not item.sales_order:
            frappe.throw(
                msg=f"Item <b>{item.item_code}</b> is a Venue. To maintain calendar integrity and prevent double-bookings, all Venues must be booked via the <b>Venue Calendar</b> first.",
                title="Direct Venue Billing Blocked"
            )

from frappe.utils import now_datetime, add_days, getdate, get_datetime

now = now_datetime()

# 1. SMART FILTERING
unpaid_orders = frappe.get_all("Sales Order", 
    filters={
        "advance_paid": ["<=", 0],         
        "docstatus": ["<", 2],             
        "custom_venue_shift": ["!=", ""],  
        "creation": ["<", add_days(now, -2)] # Broad filter: at least 48 hrs old
    }, 
    fields=["name", "creation"]
)

for order in unpaid_orders:
    # 2. PRECISION TIMING: "End of the 3rd Day" Logic
    # Example: Created Jan 1st. Expires Jan 5th at 00:00:00.
    creation_date = getdate(order.creation)
    expiry_threshold = get_datetime(add_days(creation_date, 4)) 
    
    if now < expiry_threshold:
        continue

    try:
        so_doc = frappe.get_doc("Sales Order", order.name)
        
        # Double check advance payment
        if so_doc.advance_paid <= 0:
            log_msg = "Booking cancelled automatically: Payment not recorded within the 3-day window."
            
            if so_doc.docstatus == 1:
                so_doc.add_comment("Comment", text=log_msg)
                so_doc.cancel()
            elif so_doc.docstatus == 0:
                frappe.delete_doc("Sales Order", so_doc.name)
                
    except Exception:
        frappe.log_error(f"Auto-cancel failed for {order.name}", "Venue Booking Reaper")

has_liquor = False

# Bypass RestrictedPython unpacking bug by using a single variable
liquor_bounds = frappe.db.get_value("Item Group", "Liquor", ["lft", "rgt"])

# Ensure the Liquor group actually exists in the DB before proceeding
if liquor_bounds:
    liquor_lft = liquor_bounds[0]
    liquor_rgt = liquor_bounds[1]

    for item in doc.items:
        if item.item_group:
            item_bounds = frappe.db.get_value("Item Group", item.item_group, ["lft", "rgt"])
            
            if item_bounds:
                item_lft = item_bounds[0]
                item_rgt = item_bounds[1]
                
                # If the item falls inside the Liquor tree boundaries
                if item_lft >= liquor_lft and item_rgt <= liquor_rgt:
                    has_liquor = True
                    break

if has_liquor:
    # Check if the script already ran to prevent duplicate tax rows
    tnvat_exists = False
    for tax in doc.taxes:
        if tax.account_head == "TNVAT Payable - ROC": 
            tnvat_exists = True
            break
            
    if not tnvat_exists:
        # Silently extract the TNVAT out of the inclusive grand total
        doc.append("taxes", {
            "charge_type": "On Net Total",
            "account_head": "TNVAT Payable - ROC", 
            "description": "TNVAT @ 14.5%",
            "rate": 14.5,
            "included_in_print_rate": 1  # The crucial extraction command
        })
        
        # Force the backend to recalculate the ledger split
        doc.calculate_taxes_and_totals()

# --- PART 1: VALIDATION - Restrict Direct Venue Invoicing ---
# Prevents users from adding Venues directly to an invoice without a Sales Order
RESTRICTED_GROUP = "Hall & Venue Rental"

for item in doc.items:
    # Check if the item belongs to the Venue group
    item_group = frappe.db.get_value("Item", item.item_code, "item_group")
    
    if item_group == RESTRICTED_GROUP:
        if not item.sales_order:
            frappe.throw(
                msg=f"Item <b>{item.item_code}</b> is a Venue. To maintain calendar integrity, all Venues must be booked via the <b>Venue Calendar</b> first.",
                title="Direct Venue Billing Blocked"
            )

# --- PART 2: LOGIC - POS Customer Credit Adjustment ---
# Allows POS users to pay via "Customer Account" and adjusts the paid amount accordingly
if doc.is_pos:
    credit_deduction = 0.0
    for row in doc.get('payments', []):
        if row.mode_of_payment == "Customer Account" and row.amount > 0:
            credit_deduction += float(row.amount or 0.0)
            row.amount = 0.0
            row.base_amount = 0.0
            
    if credit_deduction > 0:
        doc.paid_amount = float(doc.paid_amount or 0.0) - credit_deduction
        doc.base_paid_amount = float(doc.base_paid_amount or 0.0) - credit_deduction

# --- PART 3: LOGIC - Subscription Discount for Private Members ---
# Calculates discounts based on canteen/bar usage for specific subscription plans
if doc.subscription and doc.docstatus == 0:
    start_date = frappe.utils.get_first_day(doc.posting_date)
    end_date = doc.posting_date

    subscription_doc = frappe.get_doc("Subscription", doc.subscription)
    active_plans = [row.plan for row in subscription_doc.plans]

    is_eligible_for_discount = False
    max_discount = 0

    if 'CGF - Non Railway Member 60+' in active_plans:
        max_discount = 300
        is_eligible_for_discount = True
    elif 'CGF - Non Railway Member' in active_plans:
        max_discount = 500
        is_eligible_for_discount = True

    if is_eligible_for_discount:
        usage_invoices = frappe.get_all(
            "Sales Invoice",
            filters={
                "customer": doc.customer,
                "docstatus": 1, 
                "posting_date": ["between", [start_date, end_date]]
            },
            fields=["grand_total", "pos_profile"]
        )

        canteen_total = 0.0
        for inv in usage_invoices:
            if inv.pos_profile:
                profile_upper = inv.pos_profile.upper()
                if 'RESTAURANT' in profile_upper or 'CANTEEN' in profile_upper or 'BAR' in profile_upper:
                    canteen_total += inv.grand_total

        if canteen_total > 0:
            discount_amount = min(canteen_total, max_discount)
            doc.apply_discount_on = "Grand Total"
            doc.additional_discount_percentage = 0.0 
            doc.discount_amount = discount_amount
            doc.remarks = f"Includes a canteen/bar usage discount of {round(discount_amount, 2)}"

# --- PART 4: UI - Item Name Summary for List View ---
# Creates a comma-separated string of items for better visibility in the List View
item_names = []
for item in doc.items:
    if item.item_name and item.item_name not in item_names:
        item_names.append(item.item_name)

if len(item_names) > 3:
    summary = ", ".join(item_names[:3]) + f" (+{len(item_names)-3} more)"
else:
    summary = ", ".join(item_names)

doc.custom_items_overview = summary

# 1. Fetch all submitted, unlinked transactions across the system
existing_transactions = frappe.get_all(
    "Bank Transaction",
    filters={"docstatus": 1, "party": ["is", "not set"]},
    fields=["name", "description"]
)

keyword_lower = doc.keyword.lower()
matched_count = 0

# 2. Scan the backlog for the newly created keyword
for tx in existing_transactions:
    if tx.description and keyword_lower in tx.description.lower():

        # Directly update the database columns to bypass submission restrictions
        frappe.db.set_value("Bank Transaction", tx.name, {
            "party_type": doc.party_type,
            "party": doc.party
        })
        matched_count += 1

# 3. Leave a small message trace if executed via the UI pop-up
if matched_count > 0:
    frappe.msgprint(f"Background sweep complete: Linked {matched_count} other matching historical transactions.")
